                "嵐山・嵯峨野観光の北の玄関口として機能する、JR山陰本線（嵯峨野線）の地上駅。1897年に京都鉄道の「嵯峨駅」として開業し、1994年に現在の「嵯峨嵐山駅」へと改称、2008年には近代的な橋上駅舎へと建て替えられた。南口を出るとすぐに旧山陰本線の線路を活用したトロッコ嵯峨駅と嵐電嵯峨駅が隣接しており、列車を降りた瞬間から旅情あふれる空気に包まれる。",
